(()=>{'use strict';const el=id=>document.getElementById(id);
function review(){if(el('vlos').value!=='yes'&&el('scopeoption').value==='direct')el('scopeoption').value='unsupported';const mode=el('scopeoption').value;const reasons=[];if(el('vlos').value!=='yes'||mode==='unsupported')reasons.push('OUTSIDE SUPPORTED SCOPE: establish a supported VLOS plan; BVLOS and authorisation-specific assessment are not covered.');if(mode==='fpv'&&(!el('fpvconfirmed').checked||!el('fpvbasis').value.trim()))reasons.push('Record the adjacent FPV observer and briefing arrangement.');return{valid:reasons.length===0,mode,observer:mode==='fpv'?el('fpvbasis').value:'',confirmed:mode==='fpv'?el('fpvconfirmed').checked:null,reasons};}
window.flightScopeReview=review;
const controller=document.createElement('label');controller.className='check';controller.innerHTML='<input id="controllerready" type="checkbox"><span>Controller charge is adequate; control/link, firmware/geo-awareness and return/lost-link settings checked for this flight · GO/NO-GO required</span>';el('batteryconfirm').closest('label').before(controller);el('controllerready').addEventListener('change',()=>window.updateFlightdeskDecision?.());

function update(changed){const fpv=el('scopeoption').value==='fpv';el('fpvfields').hidden=!fpv;if(changed){el('vlos').value=el('scopeoption').value==='unsupported'?'no':'yes';el('finalconfirm').checked=false;}const r=review();el('scopestatus').textContent=r.valid?'Supported scope selected; assess VLOS in the final declaration.':r.reasons.join(' ');window.updateFlightdeskDecision?.();}
el('scopeoption').addEventListener('change',()=>update(true));el('fpvbasis').addEventListener('input',()=>{el('fpvconfirmed').checked=false;update(true);});el('fpvconfirmed').addEventListener('change',()=>update(true));
el('category').addEventListener('change',()=>{el('a2').closest('label').hidden=el('category').value!=='A2';});
const derived=[0,4,7,8],destinations={0:'crewcard',1:'airspacecard',4:'aircraftcard',7:'weathercard',8:'batterycard'};for(const i of derived){const c=el('check'+i);let label=c.closest('label');const row=document.createElement('div');row.className='check derived-check';row.append(...label.childNodes);label.replaceWith(row);label=row;c.type='hidden';c.hidden=true;c.disabled=false;c.tabIndex=-1;c.setAttribute('aria-hidden','true');label.classList.add('derived-check');const status=document.createElement('strong');status.id='derivedstatus'+i;status.className='derived-status';status.setAttribute('role','status');status.textContent='Needs attention';label.prepend(status);const p=document.createElement('p');p.className='hint';p.append('Calculated status from the originating questions. ');const link=document.createElement('a');link.href='#'+destinations[i];link.textContent='Open relevant section';p.append(link);c.closest('.checkrow').querySelector('.checkdesc').append(p);}
let controllerSignature='';window.flightSyncEvidence=function(s){const nextControllerSignature=JSON.stringify([s.aircraft,el('assetidentity')?.value,el('payloadidentity')?.value,el('height').value,el('date').value,el('hour').value,el('startminute').value,el('batteryselect').value]);if(controllerSignature&&controllerSignature!==nextControllerSignature)el('controllerready').checked=false;controllerSignature=nextControllerSignature;const crew=(r,needed)=>!!r?.name&&(!needed||!!r.registration&&/^\d{4}-\d{2}-\d{2}$/.test(r.expiry||'')&&r.expiry>=s.date);const air=window.flightAirspaceReview?.();const flags={0:s.specConfirmed&&s.open&&!window.flightReview(profile()).issues.length&&crew(s.pilot,s.flyerRequired)&&crew(s.operator,s.operatorRequired),1:!!air?.go,4:review().valid&&(!el('vloslimituse').checked||el('vloslimitconfirm').checked),7:window.FLIGHT_ASSESSMENT.weather(s).complete,8:(s.cellReviewed??s.cellCheck)&&s.batteryConfirmed&&!!s.battery&&s.battery.health!=='unknown'&&el('controllerready').checked};for(const i of derived){const c=el('check'+i),was=c.checked;c.checked=!!flags[i];el('derivedstatus'+i).textContent=c.checked?'Complete':'Needs attention';el('derivedstatus'+i).className='derived-status '+(c.checked?'complete':'attention');if(c.checked&&!was)el('checked'+i).textContent='Derived from originating checks · '+new Date().toISOString();if(!c.checked)el('checked'+i).textContent='';}el('a2').closest('label').hidden=el('category').value!=='A2';const n=Array.from(document.querySelectorAll('[data-check]')).filter(c=>c.checked).length;el('count').textContent=n+' / '+10+' recorded';el('progress').style.width=n/10*100+'%';};
update(false);
})();
